def header(active):return f'''<a class="skip" href="#main">Skip to content</a><div class="topbar"><div class="container"><a href="{mapurl}" target="_blank" rel="noopener">C.V. Arcade, Moozhikal, Kozhikode</a><span>Specialized dentistry. Personalised care.</span><a href="tel:+919496801445">+91 9496 801 445</a></div></div><header class="header"><div class="container nav"><a class="brand" href="index.html" aria-label="Cosmopolitan Dental Care home"><img src="assets/logo-lockup.png" alt="Cosmopolitan Dental Care" width="734" height="140"></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation" aria-label="Open navigation"><span></span><span></span></button><nav id="navigation" aria-label="Main navigation">{''.join(f'<a href="{file}" {"aria-current=page" if active==name else ""}>{name}</a>' for name,file in [('Home','index.html'),('About us','about.html'),('Treatments','treatments.html'),('Contact','contact.html')])}</nav>{button()}</div></header>'''
def footer():return f'''<footer><div class="container footer-grid"><div><a class="brand brand-full" href="index.html"><img src="assets/logo.png" alt="Cosmopolitan Dental Care — Specialized Dentistry, Personalised Care. Root Canal &amp; Orthodontic Centre" width="1100" height="670" loading="lazy"></a><p>Specialized dentistry.<br>Personalised care.</p><a class="social" href="{ig}" target="_blank" rel="noopener">Follow us on Instagram</a></div><div><h3>Explore</h3><a href="about.html">Our approach</a><a href="about.html#team">Our doctor panel</a><a href="treatments.html">All treatments</a><a href="contact.html">Plan your visit</a></div><div><h3>Our expertise</h3>{''.join(f'<a href="{s[0]}.html">{s[1]}</a>' for s in services if s[0] in ['root-canal-treatment','dental-implants','orthodontic-treatment','dental-pediatrics','smile-designing','microscopic-dentistry'])}<a href="treatments.html">View all services</a></div><div><h3>Visit Cosmopolitan</h3><p>C.V. Arcade, Moozhikal,<br>Kozhikode</p><a href="tel:+919496801445">+91 9496 801 445</a><a href="mailto:excalibur.unni@gmail.com">excalibur.unni@gmail.com</a><a href="{mapurl}" target="_blank" rel="noopener">Find us on Google Maps</a></div></div><div class="container footnote"><span>© 2026 Cosmopolitan Dental Care</span><span>Specialized dentistry. Personalised care.</span><a href="privacy.html">Privacy</a></div></footer>'''
def cta():return f'''<section class="container cta"><div><span class="eyebrow light">Your next chapter starts with a smile</span><h2>A healthier smile.<br>A more confident you.</h2><p>Let’s talk about what your smile needs.<br>We’re here to help you take the first step.</p>{button(cls='white')}</div><div class="tooth-art">{icon}</div></section>'''
def cards():return '<div class="service-grid">'+''.join(f'''<a class="service-card" href="{slug}.html"><div class="card-image">{img(photo,title)}</div><div class="card-content"><h3>{title}</h3><p>{desc}</p><span class="text-link">Explore treatment <span>＋</span></span></div></a>''' for slug,title,sub,desc,photo in sorted((s for s in services if s[0] in featured),key=lambda s:featured.index(s[0])))+'</div>'
