def subhero(title,text,image='consultation'):return f'''<section class="subhero"><div class="container"><div><div class="breadcrumbs"><a href="index.html">Home</a><span>/</span><span>{title}</span></div><h1>{title}</h1><p>{text}</p></div>{img(image,title,lazy=False)}</div></section>'''
